variante_1.css:
.table {
  --bs-table-bg: var(--sl-card-bg);
  --bs-table-striped-bg: rgba(var(--sl-primary-rgb), 0.05);
  --bs-table-hover-bg: rgba(var(--sl-primary-rgb), 0.1);
  --bs-table-border-color: var(--sl-border);
}

.table thead {
  border-bottom: 2px solid var(--sl-primary);
}

.table th, .table td {
  border-color: var(--sl-border);
  padding: 0.75rem 1rem;
}

.table tbody tr:last-child td {
  border-bottom: none;
}

.card {
  border-color: var(--sl-border) !important;
}

